script:
// Bemutató diákkal: lapozás a nyilakkal, minden dia egy másik tantárgy
// Slide presentation: page with the arrow keys, every slide is a different subject
stage(1000, 600, "#ffffff");

// Lapozás / paging
let page = 0, shownAt = 0, now = 0;          // aktuális dia, mikor jelent meg (s), eltelt idő (s)
const goTo = k => { page = clamp(k, 0, SLIDES.length - 1); shownAt = now; };
onKey("ArrowRight", () => goTo(page + 1), {label: "▶", help: {hu: "következő dia", en: "next slide"}});
onKey("ArrowLeft",  () => goTo(page - 1), {label: "◀", help: {hu: "előző dia", en: "previous slide"}});
update(dt => { now += dt; });

// Segédfüggvények a diákhoz / helpers for the slides
const heading = s => text(s, 60, 80, {size: 38, bold: true, color: C.blue});
const say = (s, y, o = {}) => text(s, 60, y, {size: 24, ...o});
const appear = (lt, k) => lt > 0.7 * k;      // a k-adik elem 0,7 s-onként jelenik meg / item k appears every 0.7 s

// ===== A DIÁK: mindegyik egy függvény, lt = a dia megjelenése óta eltelt idő (s) =====
// ===== THE SLIDES: each one is a function, lt = time since the slide appeared (s) =====
const SLIDES = [
  // 1. Címlap / title slide
  lt => {
    text({hu: "AnimLab – bemutató", en: "AnimLab – presentation"}, 500, 250, {size: 54, bold: true, align: "center", color: C.blue});
    text({hu: "Minden dia egy rövid függvény a kódban", en: "Every slide is a short function in the code"}, 500, 320, {size: 26, align: "center"});
    text({hu: "Lapozás: ← →", en: "Paging: ← →"}, 500, 400, {size: 22, align: "center", color: C.gray});
  },
  // 2. Matematika: másodfokú függvény / Maths: quadratic function
  lt => {
    heading({hu: "Matematika: y = a·x²", en: "Maths: y = a·x²"});
    const a = 1.5 * sin(lt), ox = 500, oy = 360, k = 40;     // a változik az időben; 1 egység = 40 px
    line(ox - 300, oy, ox + 300, oy, {stroke: C.gray}); line(ox, oy - 220, ox, oy + 200, {stroke: C.gray});
    const pts = [];
    for (let x = -5; x <= 5; x += 0.1) {
      const y = oy - a * x * x * k;
      if (y > 120 && y < 570) pts.push([ox + x * k, y]);   // csak a vásznon belüli pontok / only points on the slide
    }
    polyline(pts, {stroke: C.red, lw: 3});
    text("a = " + fmt(a, 2), 760, 160, {size: 28, bold: true});
    say({hu: "a > 0: felfelé nyílik\na < 0: lefelé nyílik", en: "a > 0: opens upwards\na < 0: opens downwards"}, 160);
  },
  // 3. Fizika: transzverzális hullám / Physics: transverse wave
  lt => {
    heading({hu: "Fizika: hullám", en: "Physics: a wave"});
    for (let k = 0; k < 40; k++) {
      const x = 100 + k * 20, y = 330 - 80 * sin(2 * PI * (k / 20 - lt / 2));   // λ = 20 pont, T = 2 s
      circle(x, y, 8, {fill: k === 10 ? C.red : C.blue});
    }
    say({hu: "A részecskék csak fel-le mozognak (piros pont),\na hullám mégis jobbra halad: c = λ / T", en: "The particles only move up and down (red dot),\nyet the wave travels to the right: c = λ / T"}, 500);
  },
  // 4. Kémia: vízmolekula / Chemistry: water molecule
  lt => {
    heading({hu: "Kémia: a vízmolekula (H₂O)", en: "Chemistry: the water molecule (H₂O)"});
    const cx = 500, cy = 330, r = 130 + 6 * sin(6 * lt), half = deg(104.5) / 2;   // a kötés rezeg / the bond vibrates
    for (const s of [-1, 1]) {
      const hx = cx + s * r * sin(half), hy = cy + r * cos(half);
      line(cx, cy, hx, hy, {stroke: C.gray, lw: 8});
      circle(hx, hy, 34, {fill: "#eeeeee", stroke: C.ink}); text("H", hx, hy, {align: "center", baseline: "middle", size: 28, bold: true});
    }
    circle(cx, cy, 55, {fill: C.red, stroke: C.ink}); text("O", cx, cy, {align: "center", baseline: "middle", size: 36, bold: true, color: "#fff"});
    text(fmt(104.5, 1) + "°", cx, cy + 105, {align: "center", size: 22});
  },
  // 5. Történelem: idővonal / History: timeline
  lt => {
    heading({hu: "Történelem: idővonal", en: "History: timeline"});
    const events = [[1000, {hu: "István királlyá koronázása", en: "Stephen crowned king"}], [1526, {hu: "Mohácsi csata", en: "Battle of Mohács"}],
                    [1848, {hu: "Forradalom és szabadságharc", en: "Revolution and war of independence"}], [1956, {hu: "Forradalom", en: "Revolution"}],
                    [1989, {hu: "A köztársaság kikiáltása", en: "Republic proclaimed"}]];
    line(80, 330, 920, 330, {stroke: C.ink, lw: 4});
    events.forEach(([year, what], k) => {
      if (!appear(lt, k)) return;
      const x = 140 + k * 180, up = k % 2 === 0, y = up ? 200 : 420;   // egyenletes térköz, felváltva fent és lent / even spacing, alternately above and below
      line(x, 330, x, up ? 240 : 395, {stroke: C.gray});
      circle(x, 330, 9, {fill: C.orange, stroke: null});
      text(String(year), x, y, {align: "center", size: 24, bold: true});
      text(what, x, y + 28, {align: "center", size: 16});
    });
  },
  // 6. Földrajz: évszakok / Geography: seasons
  lt => {
    heading({hu: "Földrajz: az évszakok", en: "Geography: the seasons"});
    const a = lt / 2, ex = 500 + 300 * cos(a), ey = 330 + 150 * sin(a);   // a Föld pályája / Earth's orbit
    ellipse(500, 330, 300, 150, {stroke: C.light, fill: null});
    circle(500, 330, 45, {fill: C.yellow, stroke: C.orange});
    circle(ex, ey, 24, {fill: C.blue, stroke: null});
    line(ex - 30 * sin(deg(23.4)), ey + 30 * cos(deg(23.4)), ex + 30 * sin(deg(23.4)), ey - 30 * cos(deg(23.4)), {stroke: C.ink, lw: 2});   // a tengely mindig ugyanarra dől / the axis always tilts the same way
    const seasons = [{hu: "nyár", en: "summer"}, {hu: "ősz", en: "autumn"}, {hu: "tél", en: "winter"}, {hu: "tavasz", en: "spring"}];
    say(seasons[floor(mod(a + PI / 4 + PI, 2 * PI) / (PI / 2))], 540, {bold: true});   // az északi féltekén / northern hemisphere
    say({hu: "A tengely 23,4°-os dőlése okozza, nem a távolság.", en: "Caused by the 23.4° tilt of the axis, not by the distance."}, 580, {size: 18, color: C.gray});
  },
  // 7. Nyelvek: szókártyák / Languages: word cards
  lt => {
    heading({hu: "Nyelvek: szókártyák", en: "Languages: word cards"});
    const words = [["alma", "apple"], ["ház", "house"], ["fa", "tree"], ["könyv", "book"]];
    const n = floor(lt / 3) % words.length, flip = lt % 3 > 1.5;      // 3 s-onként új kártya, félidőben fordul
    const w = 360 * abs(cos(PI * clamp((lt % 3 - 1.3) / 0.4, 0, 1)));  // a fordulás: a kártya elkeskenyedik / the flip narrows the card
    rect(500 - w / 2, 220, w, 200, {fill: flip ? "#e7f6ea" : "#fff4e0", stroke: C.ink, radius: 14});
    if (w > 40) text(flip ? words[n][1] : words[n][0], 500, 330, {align: "center", baseline: "middle", size: 48, bold: true});
    text(flip ? "English" : "Magyar", 500, 460, {align: "center", size: 20, color: C.gray});
  },
  // 8. Zárás / closing
  lt => {
    heading({hu: "Készíts saját diát!", en: "Make your own slide!"});
    say({hu: "1. Másold le egy dia függvényét a SLIDES listában.", en: "1. Copy the function of a slide in the SLIDES list."}, 180);
    say({hu: "2. Írd át a címet és a rajzot.", en: "2. Change the heading and the drawing."}, 230);
    say({hu: "3. Ctrl+Enter – kész.", en: "3. Ctrl+Enter – done."}, 280);
    if (appear(lt, 1)) text({hu: "Köszönöm a figyelmet!", en: "Thank you for your attention!"}, 500, 430, {size: 40, bold: true, align: "center", color: C.blue});
  },
];

draw(t => {
  const lt = now - shownAt;
  SLIDES[page](lt);                          // az aktuális dia / the current slide
  // lábléc: oldalszám és haladásjelző / footer: page number and progress bar
  rect(0, 590, 1000 * (page + 1) / SLIDES.length, 10, {fill: C.blue, stroke: null});
  text((page + 1) + " / " + SLIDES.length, 960, 575, {align: "right", size: 16, color: C.gray});
  show({hu: "Dia", en: "Slide"}, (page + 1) + " / " + SLIDES.length);
});
